def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    colors = {5: 8, 7: 4, 9: 3}
    for r1 in range(h):
        for r2 in range(r1 + 2, h):
            for c1 in range(w):
                for c2 in range(c1 + 2, w):
                    if r2-r1 != c2-c1 or r2-r1+1 not in colors:
                        continue
                    if (all(grid[r1][c] == 2 and grid[r2][c] == 2 for c in range(c1,c2+1)) and
                        all(grid[r][c1] == 2 and grid[r][c2] == 2 for r in range(r1,r2+1))):
                        for r in range(r1+1,r2):
                            for c in range(c1+1,c2):
                                if grid[r][c] == 0:
                                    out[r][c] = colors[r2-r1+1]
    return out
